<?php
require_once __DIR__ . '/config.php'; require_admin(); $pageTitle='Ventas — Lechugas'; require __DIR__ . '/includes/header.php'; $rows=db()->query('SELECT v.*,u.nombre AS cliente,p.nombre AS producto FROM ventas v JOIN usuarios u ON u.id=v.usuario_id JOIN productos p ON p.id=v.producto_id ORDER BY v.fecha DESC')->fetchAll(); ?>
<main><section class="page-hero"><div class="container"><span class="eyebrow">PANEL DE ADMINISTRACIÓN</span><h1>Registro de <em>ventas.</em></h1></div></section><section class="section-pad"><div class="container"><div class="table-responsive admin-list"><table class="table align-middle"><thead><tr><th>Fecha</th><th>Cliente</th><th>Producto</th><th>Cantidad</th><th>Precio unitario</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e($row['fecha']) ?></td><td><?= e($row['cliente']) ?></td><td><?= e($row['producto']) ?></td><td><?= (int)$row['cantidad'] ?></td><td><?= money($row['precio_unitario']) ?></td><td><strong><?= money($row['total']) ?></strong></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><p>Aún no hay ventas registradas.</p><?php endif; ?></div></div></section></main><?php require __DIR__ . '/includes/footer.php'; ?>
